// Generated by Lienzo UI. Runtime helper shared by every design: do not edit by hand.
// Holds the landscape and the portrait state of the elements that the design lays out differently and
// applies one of them when the screen orientation changes (Screen.width < Screen.height = portrait).
using System;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

[DisallowMultipleComponent]
public class LienzoOrientationLayout : MonoBehaviour
{
    [Serializable]
    public class LayoutState
    {
        /// 0 none, 1 horizontal, 2 vertical, 3 grid (same numbers as the Lienzo file).
        public int mode;
        public int left, right, top, bottom;
        public Vector2 spacing, cellSize;
        public int childAlignment;
        public bool expandWidth, expandHeight;
    }

    [Serializable]
    public class State
    {
        public bool hasRect;
        public Vector2 anchorMin = new Vector2(0.5f, 0.5f), anchorMax = new Vector2(0.5f, 0.5f), pivot = new Vector2(0.5f, 0.5f);
        public Vector2 anchoredPosition, sizeDelta;
        public float rotationZ;
        public bool hasActive, active = true;
        /// 0 = leave the font size alone.
        public float fontSize;
        public bool hasLayout;
        public LayoutState layout = new LayoutState();
        /// ScrollView content height (Entry.content); hasContent = this state sets it.
        public bool hasContent;
        public float contentHeight;
    }

    [Serializable]
    public class Entry
    {
        public RectTransform target;
        public TMP_Text[] texts;
        /// Object that carries the layout group (a ScrollView's content, or the target itself).
        public Transform layoutHolder;
        /// A ScrollView's Content: its height can differ per orientation (it depends on the children's boxes).
        public RectTransform content;
        public State landscape = new State();
        public State portrait = new State();
    }

    public Entry[] entries = new Entry[0];

    int current = -1; // -1 unknown, 0 landscape, 1 portrait

    void OnEnable() => Apply(Screen.width < Screen.height);

    void Update()
    {
        var p = Screen.width < Screen.height ? 1 : 0;
        if (p != current) Apply(p == 1);
    }

    void OnRectTransformDimensionsChange()
    {
        if (isActiveAndEnabled) Apply(Screen.width < Screen.height);
    }

    /// Applies the portrait (true) or the landscape (false) state of every entry.
    public void Apply(bool portrait)
    {
        current = portrait ? 1 : 0;
        if (entries == null) return;
        foreach (var e in entries)
        {
            if (e == null) continue;
            var s = portrait ? e.portrait : e.landscape;
            if (s == null) continue;
            if (s.hasContent && e.content != null) e.content.sizeDelta = new Vector2(e.content.sizeDelta.x, s.contentHeight);
            if (e.target == null) continue;
            if (s.hasRect)
            {
                e.target.anchorMin = s.anchorMin;
                e.target.anchorMax = s.anchorMax;
                e.target.pivot = s.pivot;
                e.target.anchoredPosition = s.anchoredPosition;
                e.target.sizeDelta = s.sizeDelta;
                e.target.localEulerAngles = new Vector3(0, 0, s.rotationZ);
            }
            if (s.hasActive && e.target.gameObject.activeSelf != s.active) e.target.gameObject.SetActive(s.active);
            if (s.fontSize > 0 && e.texts != null)
                foreach (var t in e.texts)
                {
                    if (t == null) continue;
                    var tm = t as TextMeshProUGUI;
                    if (tm != null && tm.enableAutoSizing)
                    {
                        tm.fontSizeMax = s.fontSize;
                        tm.fontSizeMin = Mathf.Max(1f, s.fontSize * 0.5f);
                    }
                    t.fontSize = s.fontSize;
                }
            if (s.hasLayout) ApplyLayout(e.layoutHolder != null ? e.layoutHolder : e.target, s.layout);
        }
    }

    // Changing the layout MODE between orientations is not supported at runtime (a GameObject cannot hold two
    // layout groups): the group that exists is updated when its type matches, otherwise it is left untouched.
    static void ApplyLayout(Transform holder, LayoutState l)
    {
        if (holder == null || l == null) return;
        var ro = new RectOffset(l.left, l.right, l.top, l.bottom);
        if (l.mode == 3)
        {
            var g = holder.GetComponent<GridLayoutGroup>();
            if (g == null) return;
            g.padding = ro;
            g.cellSize = l.cellSize;
            g.spacing = l.spacing;
            g.childAlignment = (TextAnchor)l.childAlignment;
            return;
        }
        if (l.mode != 1 && l.mode != 2) return;
        var hv = holder.GetComponent<HorizontalOrVerticalLayoutGroup>();
        if (hv == null || (l.mode == 1) != (hv is HorizontalLayoutGroup)) return;
        hv.padding = ro;
        hv.spacing = l.mode == 1 ? l.spacing.x : l.spacing.y;
        hv.childAlignment = (TextAnchor)l.childAlignment;
        hv.childControlWidth = l.expandWidth;
        hv.childControlHeight = l.expandHeight;
        hv.childForceExpandWidth = l.expandWidth;
        hv.childForceExpandHeight = l.expandHeight;
    }
}
